+        grid.addColumn(ContactMessage::email).setHeader("Email").setAutoWidth(true);
+        grid.addColumn(ContactMessage::phone).setHeader("Phone").setAutoWidth(true);
+        grid.addColumn(ContactMessage::message).setHeader("Message").setFlexGrow(1);
+        refreshGrid();
+
+        add(new H1("Contact"), new RouterLink("About", AboutView.class), form, grid);
+    }
+
+    private List<TextFieldBase<?, String>> fields() {
+        return List.of(name, email, phone, message);
+    }
+
+    private void trySend() {
+        if (!validate()) {
+            return;
+        }
+        messageService.send(new ContactMessage(name.getValue().strip(), email.getValue().strip(),
+                phone.getValue().strip(), message.getValue(), Instant.now()));
+        refreshGrid();
+        Notification.show("Message sent");
+
+        name.clear();
+        email.clear();
+        phone.clear();
+        message.clear();
+        // Clearing fires value change events; disable afterwards until the next edit
+        send.setEnabled(false);
+    }
+
+    private boolean validate() {
+        boolean valid = true;
+        valid &= check(name, name.getValue().isBlank() ? "Name is required" : null);
+
+        String emailValue = email.getValue().strip();
+        String emailError = null;
+        if (!emailValue.isEmpty() && !EMAIL.matcher(emailValue).matches()) {
+            emailError = "Enter a valid e-mail address";
+        } else if (emailValue.isEmpty() && phone.getValue().isBlank()) {
+            emailError = "Give an e-mail address or a phone number";
+        }
+        valid &= check(email, emailError);
+        phone.setInvalid(false);
+
+        String messageValue = message.getValue();
+        String messageError = null;
+        if (messageValue.isBlank()) {
+            messageError = "Message is required";
+        } else if (messageValue.length() > MAX_MESSAGE_LENGTH) {
+            messageError = "Message must be at most " + MAX_MESSAGE_LENGTH + " characters";
+        }
+        valid &= check(message, messageError);
+        return valid;
+    }
+
+    private static boolean check(HasValidationProperties field, String error) {
+        field.setErrorMessage(error);
+        field.setInvalid(error != null);
+        return error == null;
+    }
+
+    private void refreshGrid() {
+        grid.setItems(messageService.findAll());
+    }
+
+    private boolean hasUnsavedInput() {
+        return !name.isEmpty() || !email.isEmpty() || !phone.isEmpty() || !message.isEmpty();
+    }
+
+    private void keepEditing(BeforeLeaveEvent.ContinueNavigationAction action) {
+        leaveDialog.close();
+        // Tell the client router the navigation is off, so later navigations are not blocked
+        action.cancel();
+    }
+
+    @Override
+    public void beforeLeave(BeforeLeaveEvent event) {
+        if (!hasUnsavedInput()) {
+            return;
+        }
+        var action = event.postpone();
+        if (leaveDialog != null) {
+            leaveDialog.close();
+        }
+        leaveDialog = new Dialog();
+        leaveDialog.setHeaderTitle("Unsent message");
+        leaveDialog.add("Leave this page and lose what you have typed?");
+        leaveDialog.setCloseOnOutsideClick(false);
+        // Escape behaves like "Keep editing"
+        leaveDialog.addDialogCloseActionListener(e -> keepEditing(action));
+        var keepEditing = new Button("Keep editing", e -> keepEditing(action));
+        var discard = new Button("Discard", e -> {
+            leaveDialog.close();
+            action.proceed();
+        });
+        discard.addThemeVariants(ButtonVariant.ERROR);
+        leaveDialog.getFooter().add(keepEditing, discard);
+        leaveDialog.open();
+    }
+}
