+        page.getByText("Keep editing").click();
+        PlaywrightAssertions.assertThat(page.locator("h1")).hasText("Contact");
+        assertEquals("1", page.getByLabel("Phone").inputValue());
+        page.locator("a", new Page.LocatorOptions().setHasText("About")).click();
+        page.getByText("Discard").click();
+        PlaywrightAssertions.assertThat(page.locator("h1")).hasText("About");
+        page.locator("a", new Page.LocatorOptions().setHasText("Contact")).click();
+        PlaywrightAssertions.assertThat(page.locator("vaadin-grid-cell-content", new Page.LocatorOptions().setHasText("Hello there")).first()).isVisible();
+        page.locator("a", new Page.LocatorOptions().setHasText("About")).click();
